const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const s = lines.join(' ').split(/\s+/).filter(x => x.length)[0];
const n = s.length;
let sa = Array.from({ length: n }, (_, i) => i);
let rank = Array.from(s, c => c.charCodeAt(0));
for (let k = 1; ; k *= 2) {
  const key2 = i => (i + k < n ? rank[i + k] : -1);
  sa.sort((a, b) => rank[a] - rank[b] || key2(a) - key2(b));
  const nr = new Array(n).fill(0);
  for (let idx = 1; idx < n; idx++) {
    const a = sa[idx - 1], b = sa[idx];
    nr[b] = nr[a] + ((rank[a] !== rank[b] || key2(a) !== key2(b)) ? 1 : 0);
  }
  rank = nr;
  if (rank[sa[n - 1]] === n - 1) break;
}
const lcp = new Array(n).fill(0);
let h = 0;
for (let i = 0; i < n; i++) {
  if (rank[i] > 0) {
    const j = sa[rank[i] - 1];
    while (i + h < n && j + h < n && s[i + h] === s[j + h]) h++;
    lcp[rank[i]] = h;
    if (h > 0) h--;
  } else h = 0;
}
let sum = 0;
for (const v of lcp) sum += v;
console.log(String(n * (n + 1) / 2 - sum));

