import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().trim();
        int n = s.length();
        Integer[] sa = new Integer[n];
        int[] rank = new int[n];
        for (int i = 0; i < n; i++) { sa[i] = i; rank[i] = s.charAt(i); }
        for (int k = 1; ; k *= 2) {
            final int[] r = rank;
            final int kk = k;
            Arrays.sort(sa, (a, b) -> {
                if (r[a] != r[b]) return Integer.compare(r[a], r[b]);
                int ra = a + kk < n ? r[a + kk] : -1, rb = b + kk < n ? r[b + kk] : -1;
                return Integer.compare(ra, rb);
            });
            int[] nr = new int[n];
            for (int idx = 1; idx < n; idx++) {
                int a = sa[idx - 1], b = sa[idx];
                int ra = a + k < n ? r[a + k] : -1, rb = b + k < n ? r[b + k] : -1;
                nr[b] = nr[a] + ((r[a] != r[b] || ra != rb) ? 1 : 0);
            }
            rank = nr;
            if (rank[sa[n - 1]] == n - 1) break;
        }
        int[] lcp = new int[n];
        int h = 0;
        for (int i = 0; i < n; i++) {
            if (rank[i] > 0) {
                int j = sa[rank[i] - 1];
                while (i + h < n && j + h < n && s.charAt(i + h) == s.charAt(j + h)) h++;
                lcp[rank[i]] = h;
                if (h > 0) h--;
            } else h = 0;
        }
        long total = (long) n * (n + 1) / 2;
        for (int v : lcp) total -= v;
        System.out.println(total);
    }
}

