#include <bits/stdc++.h>
using namespace std;
int main() {
    string s;
    cin >> s;
    int n = s.size();
    vector<int> sa(n), rnk(n), tmp(n);
    iota(sa.begin(), sa.end(), 0);
    for (int i = 0; i < n; i++) rnk[i] = s[i];
    for (int k = 1;; k *= 2) {
        auto key2 = [&](int i) { return i + k < n ? rnk[i + k] : -1; };
        sort(sa.begin(), sa.end(), [&](int a, int b) {
            if (rnk[a] != rnk[b]) return rnk[a] < rnk[b];
            return key2(a) < key2(b);
        });
        tmp[sa[0]] = 0;
        for (int i = 1; i < n; i++)
            tmp[sa[i]] = tmp[sa[i - 1]] + ((rnk[sa[i - 1]] != rnk[sa[i]] || key2(sa[i - 1]) != key2(sa[i])) ? 1 : 0);
        rnk = tmp;
        if (rnk[sa[n - 1]] == n - 1) break;
    }
    vector<int> lcp(n, 0);
    int h = 0;
    for (int i = 0; i < n; i++) {
        if (rnk[i] > 0) {
            int j = sa[rnk[i] - 1];
            while (i + h < n && j + h < n && s[i + h] == s[j + h]) h++;
            lcp[rnk[i]] = h;
            if (h > 0) h--;
        } else h = 0;
    }
    long long total = (long long)n * (n + 1) / 2;
    for (int v : lcp) total -= v;
    printf("%lld\n", total);
    return 0;
}
